Future<void> showCaseProgressSheet(
  BuildContext context,
  String caseId, {
  bool fromDeleted = false,
}) => showModalBottomSheet<void>(
  context: context,
  isScrollControlled: true,
  useSafeArea: true,
  showDragHandle: true,
  builder: (_) => FractionallySizedBox(
    heightFactor: 0.9,
    child: CaseStatusScreen(caseId: caseId, fromDeleted: fromDeleted),
  ),
);

class CaseStatusScreen extends ConsumerWidget {
  const CaseStatusScreen({
    super.key,
    required this.caseId,
    this.fromDeleted = false,
  });

  /// True only when opened from the Deleted filter; enables permanent delete.
  final bool fromDeleted;

  final String caseId;

  @override
  Widget build(BuildContext context, WidgetRef ref) => Scaffold(
    appBar: AppBar(title: const Text('Case progress')),
    body: SafeArea(
      child: ref
          .watch(caseStatusProvider(caseId))
          .when(
            loading: () => const LoadingStateView(label: 'Loading case'),
            error: (_, _) => ErrorRetryView(
              onRetry: () => ref.invalidate(caseStatusProvider(caseId)),
            ),
            data: (item) {
              if (item == null) {
                return const EmptyStateView(
                  title: 'Case not found',
                  message:
                      'Return to case status and choose an available case.',
                );
              }
              if (item.status == 'ESCALATED') {
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (context.mounted) context.go('/emergency');
                });
                return const LoadingStateView(
                  label: 'Opening emergency referral',
                );
              }
              if (item.status == 'FAILED_SAFE') {
                return ListView(
                  padding: const EdgeInsets.all(16),
                  children: [
                    _NoticeCard(
                      icon: Icons.health_and_safety_outlined,
                      color: context.glass.warning,
                      title: 'This request could not be prepared for review',
                      message:
                          '${failureReason(item.failureCode)} No automated guidance will be shown. Your doctor can still see this request. If you are worried or symptoms get worse, see a clinician in person. For an emergency, call 1990.',
                    ),
                    if (item.submittedEpisode != null) ...[
                      const SizedBox(height: 12),
                      _SubmittedRequestCard(episode: item.submittedEpisode!),
                    ],
                    RequestSubmissionActions(item: item),
                  ],
                );
              }
              if ({'WITHDRAWN', 'SUPERSEDED'}.contains(item.status)) {
                return ListView(
                  padding: const EdgeInsets.all(24),
                  children: [
                    Text(
                      item.status == 'WITHDRAWN'
                          ? 'This request was deleted.'
                          : 'This request was replaced by your edited submission.',
                    ),
                    if (item.status == 'WITHDRAWN' && fromDeleted)
                      RequestSubmissionActions(item: item, allowPurge: true),
                  ],
                );
              }
              // A decided case is no longer overdue, even if an older delay marker is still present.
              final delayed =
                  item.failureCode == 'DOCTOR_RESPONSE_DELAY' &&
                  item.latestDecisionAction == null &&
                  !item.hasApprovedGuidance;
              return ListView(
                padding: const EdgeInsets.all(16),
                children: [
                  _ProgressCard(item: item),
                  if (item.submittedEpisode != null) ...[
                    const SizedBox(height: 12),
                    _SubmittedRequestCard(episode: item.submittedEpisode!),
                  ],
                  if (item.status == 'CLAIMED')
                    _NoticeCard(
                      icon: Icons.lock_outline,
                      color: Theme.of(context).colorScheme.primary,
                      title: 'Claimed by a doctor',
                      message:
                          'A doctor has claimed this request, so it can no longer be deleted. Contact your doctor if it was sent by mistake.',
                    ),
                  if (item.latestDecisionAction != null)
                    _NoticeCard(
                      icon: Icons.message_outlined,
                      color: Theme.of(context).colorScheme.primary,
                      title: 'Doctor response',
                      message: 'Your doctor has responded to this request.',
                    ),
                  const SizedBox(height: 12),
                  if (delayed)
                    _NoticeCard(
                      icon: Icons.schedule_outlined,
                      color: context.glass.warning,
                      title: 'Doctor review is taking longer',
                      message:
                          'A doctor has not responded within the expected review window. Please arrange an in-person clinical review. If symptoms worsen or become urgent, use emergency services.',
                    )
                  else if (item.hasApprovedGuidance)
                    ElevatedButton.icon(
                      onPressed: () => context.push('/guidance/$caseId'),
                      icon: const Icon(Icons.verified_outlined),
                      label: const Text('View approved guidance'),
                    )
                  else if (item.latestDecisionAction == null)
                    _NoticeCard(
                      icon: Icons.lock_outline,
                      color: Theme.of(context).colorScheme.primary,
                      title: 'Waiting for doctor approval',
                      message:
                          'Guidance remains hidden until a doctor reviews and approves it.',
                    ),
                  const SizedBox(height: 16),
                  RequestSubmissionActions(item: item),
                ],
              );
            },
          ),
    ),
  );
}

/// Only the patient's submitted input; never agent output or doctor-only notes.
class _SubmittedRequestCard extends StatelessWidget {
  const _SubmittedRequestCard({required this.episode});
  final Map<String, dynamic> episode;

  @override
  Widget build(BuildContext context) {
    final symptoms =
        (episode['symptoms'] as List?)?.whereType<String>().toList() ??
        const <String>[];
    final notes = episode['notes'] as String?;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Your submitted details',
              style: Theme.of(context).textTheme.titleMedium,
            ),
            const SizedBox(height: 8),
            const Text(
              'These are the details you entered, not automated guidance.',
            ),
            const SizedBox(height: 12),
            const Text('Symptoms and description'),
            SelectableText(
              symptoms.isEmpty ? 'No symptoms recorded' : symptoms.join(', '),
            ),
            const SizedBox(height: 8),
            Text('Duration: ${episode['durationDays']} days'),
            Text('Severity: ${episode['severity']}/10'),
            if (notes != null && notes.trim().isNotEmpty) ...[
              const SizedBox(height: 8),
              const Text('Additional notes'),
              SelectableText(notes),
            ],
          ],
        ),
      ),
    );
  }
}

/// Opaque card holding the progress rail — status is clinical content, so no glass.
class _ProgressCard extends StatelessWidget {
  const _ProgressCard({required this.item});

  final TriageCase item;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final step = item.hasApprovedGuidance || item.latestDecisionAction != null
        ? 4
        : StatusStepper.indexOf(item.status) + 1;
    final total = StatusStepper.stepCount;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Expanded(
                  child: Text(
                    'Request progress',
                    style: theme.textTheme.titleMedium,
                  ),
                ),
                Text(
                  'Step $step of $total',
                  style: theme.textTheme.labelMedium?.copyWith(
                    color: scheme.primary,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ],
            ),
            const SizedBox(height: 2),
            Text(
              'Submitted ${DateFormat.yMMMd().format(item.submittedAt)}',
              style: theme.textTheme.bodySmall?.copyWith(
                color: scheme.onSurfaceVariant,
              ),
            ),
            const SizedBox(height: 12),
            // Decorative: the "Step x of y" text above already states the position.
            ExcludeSemantics(
              child: ClipRRect(
                borderRadius: BorderRadius.circular(4),
                child: LinearProgressIndicator(
                  value: step / total,
                  minHeight: 6,
                  backgroundColor: scheme.outlineVariant,
                ),
              ),
            ),
            const SizedBox(height: 20),
            for (final (label, value) in [
              (
                'Request received',
                DateFormat.yMMMd().add_jm().format(item.submittedAt.toLocal()),
              ),
              (
                'Doctor received request',
                item.doctorReceivedAt == null
                    ? 'Awaiting receipt'
                    : DateFormat.yMMMd().add_jm().format(
                        item.doctorReceivedAt!.toLocal(),
                      ),
              ),
              (
                'AI processing',
                switch (item.status) {
                  'PLANNING' ||
                  'CONTEXT_READY' ||
                  'ANALYSED' ||
                  'RISK_ASSESSED' ||
                  'VALIDATED' => 'In progress',
                  'PENDING_DOCTOR_REVIEW' => 'Prepared for doctor review',
                  'LOW_CONFIDENCE' || 'FAILED_SAFE' => 'Stopped safely',
                  'CLAIMED' => 'Doctor has taken over',
                  'APPROVED' ||
                  'APPROVED_REVISED' ||
                  'DELIVERED' ||
                  'CLOSED' ||
                  'REJECTED' => 'Doctor response available',
                  _ => 'Waiting',
                },
              ),
              (
                'Doctor review',
                item.doctorReviewStartedAt == null
                    ? 'Not started'
                    : 'Started ${DateFormat.yMMMd().add_jm().format(item.doctorReviewStartedAt!.toLocal())}',
              ),
              (
                'Doctor response',
                item.latestDecisionAction != null || item.hasApprovedGuidance
                    ? 'Received'
                    : 'Waiting',
              ),
            ])
              ListTile(
                contentPadding: EdgeInsets.zero,
                title: Text(label),
                subtitle: Text(value),
              ),
          ],
        ),
      ),
    );
  }
}

class _NoticeCard extends StatelessWidget {
  const _NoticeCard({
    required this.icon,
    required this.color,
    required this.title,
    required this.message,
  });

  final IconData icon;
  final Color color;
  final String title;
  final String message;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              width: 40,
              height: 40,
              decoration: BoxDecoration(
                color: color.withValues(alpha: 0.14),
                shape: BoxShape.circle,
              ),
              child: Icon(icon, color: color, size: 22),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(title, style: theme.textTheme.titleSmall),
                  const SizedBox(height: 4),
                  Text(message, style: theme.textTheme.bodyMedium),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}
